<?php require __DIR__.'/includes/bootstrap.php';$error='';if(is_post()){verify_csrf();$email=trim((string)post('email'));$pass=(string)post('password');$st=db()->prepare('SELECT * FROM users WHERE email=? AND status=1 LIMIT 1');$st->execute([$email]);$u=$st->fetch();if($u&&password_verify($pass,$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'phone'=>$u['phone'],'role'=>$u['role']];redirect($u['role']==='admin'?'/admin/index.php':'/account.php');}$error='Invalid credentials.';}$title='Login';require __DIR__.'/includes/header.php';?><div class="min-h-[70vh] grid place-items-center px-4 py-12"><div class="max-w-md w-full bg-white border rounded-[28px] p-7 soft"><div class="font-black text-2xl">Welcome back</div><div class="text-sm text-slate-500 mt-1">Login to PAROKO.</div><?php if($error):?><div class="mt-4 p-3 rounded-xl bg-rose-50 text-rose-700 text-sm"><?=e($error)?></div><?php endif;?><form method="post" class="mt-6 space-y-3"><?=csrf_input()?><input required type="email" name="email" placeholder="Email" class="w-full rounded-xl border-slate-200"><input required type="password" name="password" placeholder="Password" class="w-full rounded-xl border-slate-200"><button class="w-full py-3 rounded-xl bg-slate-950 text-white font-black">Login</button></form><div class="mt-5 text-xs text-slate-400">Demo admin: <?=DEMO_ADMIN_EMAIL?> / <?=DEMO_ADMIN_PASSWORD?></div></div></div><?php require __DIR__.'/includes/footer.php';?>
